from typing import Optional

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class MiniAppsMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.miniapps.api_miniapps_list")
    def api_miniapps_list(self):
        return self.post(path="api/miniapp/list")

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_enable")
    def api_miniapps_enable(self, miniapp_id: str):
        return self.post(path="api/miniapp/enable", json={"miniappId": miniapp_id})

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_disable")
    def api_miniapps_disable(self, miniapp_id: str):
        return self.post(path="api/miniapp/disable", json={"miniappId": miniapp_id})

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_delete")
    def api_miniapps_delete(self, miniapp_id: str):
        return self.post(path="api/miniapp/delete", json={"miniappId": miniapp_id})

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_reorder")
    def api_miniapps_reorder(self, miniapp_ids: list[str]):
        return self.post(path="api/miniapp/reorder", json={"miniappIds": miniapp_ids})

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_get")
    def api_miniapps_get(self, miniapp_id: str):
        return self.post(path="api/miniapp/get", json={"miniappId": miniapp_id})

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_create")
    def api_miniapps_create(
        self,
        name: str,
        description: str,
        filled_icon_id: str,
        outlined_icon_id: str,
        showcase_icon_id: str,
        allowed_cross_origin_api_hosts: Optional[list[str]] = (),
    ):
        return self.post(
            path="api/miniapp/create",
            json={
                "name": name,
                "description": description,
                "filledIconId": filled_icon_id,
                "outlinedIconId": outlined_icon_id,
                "showcaseIconId": showcase_icon_id,
                "allowedCrossOriginApiHosts": allowed_cross_origin_api_hosts,
            },
        )

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_edit")
    def api_miniapps_edit(
        self,
        miniapp_id: str,
        name: str,
        description: str,
        filled_icon_id: str,
        outlined_icon_id: str,
        showcase_icon_id: str,
        allowed_cross_origin_api_hosts: Optional[list[str]] = (),
    ):
        return self.post(
            path="api/miniapp/edit",
            json={
                "miniappId": miniapp_id,
                "name": name,
                "description": description,
                "filledIconId": filled_icon_id,
                "outlinedIconId": outlined_icon_id,
                "showcaseIconId": showcase_icon_id,
                "allowedCrossOriginApiHosts": allowed_cross_origin_api_hosts,
            },
        )

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_backend_set")
    def api_miniapps_backend_set(
        self,
        miniapp_id: str,
        start_url: Optional[str] = None,
        backend_url: Optional[str] = None,
        backend_certificate: Optional[str] = None,
    ):
        return self.post(
            path="api/miniapp/backend/set",
            json={
                "miniappId": miniapp_id,
                "startUrl": start_url,
                "backend": {
                    "url": backend_url,
                    "certificate": backend_certificate,
                },
            },
        )

    @tracer.start_as_current_span("admin.miniapps.api_miniapps_links_get_сonfig")
    def api_miniapp_links_get_сonfig(
        self,
        domain: str,
    ):
        """
        Получить ссылки для домена
        :param domain: Домен, для которого нужно получить ссылки
        :return: тело ответа сервера
        """
        return self.post(
            path="api/miniapp/links/getConfig",
            json={"domain": domain},
        )

    @tracer.start_as_current_span("admin.miniapps.api_miniapp_links_set_сonfig")
    def api_miniapp_links_set_сonfig(
        self,
        domain: str,
        links: list[dict[str, str]],
    ):
        """
        Задать ссылки для домена
        :param domain: Домен, для которого нужно получить ссылки
        param link: заданный URL
        param name: Название ссылки
        :return: тело ответа сервера
        """
        return self.post(
            path="api/miniapp/links/setConfig",
            json={
                "domain": domain,
                "links": links,
            },
        )

    @tracer.start_as_current_span("admin.miniapps.api_miniapp_links_delete_domain")
    def api_miniapp_links_delete_domain(
        self,
        domain: str,
    ):
        """
        Удалить домен со ссылками
        :param domain: Домен, для которого нужно получить ссылки
        :return: тело ответа сервера
        """
        return self.post(
            path="api/miniapp/links/deleteDomain",
            json={"domain": domain},
        )
